from pathlib import Path
import base64
BASE=Path(__file__).resolve().parent
argos=base64.b64encode((BASE/'argos/dist/index.html').read_bytes()).decode()
claude=base64.b64encode((BASE/'claude/dist/index.html').read_bytes()).decode()
page=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ClearHot · Six Method Review</title><style>
:root{color-scheme:dark;font:15px/1.45 system-ui,sans-serif;background:#080f1c;color:#d9e5f2}*{box-sizing:border-box}body{margin:0}header{padding:25px clamp(16px,3vw,42px);background:linear-gradient(125deg,#10283c,#11192b 58%,#21152c);border-bottom:1px solid #314254}.head{max-width:1600px;margin:auto}.eyebrow{color:#6de1d0;text-transform:uppercase;letter-spacing:.16em;font-size:11px;font-weight:800}h1{font-size:clamp(24px,3vw,38px);letter-spacing:-.03em;margin:5px 0}p{margin:7px 0}small,.muted{color:#a6bacb}.note{max-width:1600px;margin:14px auto;background:#382a19;color:#ffe0ac;padding:13px 16px;border:1px solid #896131;border-radius:10px}main{max-width:1600px;margin:auto;padding:0 clamp(12px,2vw,28px) 30px}.nav{display:flex;gap:7px;flex-wrap:wrap;margin:16px 0}button,.file{font:inherit;font-size:13px;color:#d6e3ef;background:#132337;border:1px solid #3a5065;border-radius:9px;padding:9px 12px;cursor:pointer}button:hover,.file:hover{border-color:#69d5c8}button.active{background:#15554f;border-color:#71decf;color:white}button:focus-visible,input:focus-visible{outline:3px solid #71decf}button:disabled{opacity:.45;cursor:not-allowed}.tools{background:#101e2e;border:1px solid #31465a;border-radius:12px;padding:15px;display:flex;gap:16px;flex-wrap:wrap;align-items:center}.file{display:inline-flex;border-color:#65cebe;font-weight:700}.file input{display:none}.seek{min-width:220px;flex:1}.seek input{width:100%;accent-color:#60d9c5}.status{font-size:12px;color:#b6c8d7}.tabs-title{font-size:12px;color:#a8bccc;margin:20px 0 8px;text-transform:uppercase;letter-spacing:.1em}.description{padding:13px 15px;background:#122337;border:1px solid #274359;border-radius:10px;margin:12px 0;color:#ccdeeb}.grid{display:grid;grid-template-columns:minmax(0,1fr);gap:14px}.grid.both{grid-template-columns:repeat(2,minmax(0,1fr))}@media(max-width:1050px){.grid.both{grid-template-columns:1fr}}.pane{min-width:0;background:#060c15;border:1px solid #2d465d;border-radius:12px;overflow:hidden}.pane h2{font-size:13px;padding:9px 13px;margin:0;background:#152b3c;color:#a5dcd7}.pane iframe{display:block;width:100%;height:1200px;border:0;background:#060c15}.pane[hidden]{display:none}.foot{color:#a0b0c1;font-size:12px;margin:16px 0}.error{color:#ffae9e}
</style></head><body><header><div class="head"><div class="eyebrow">Independent review · six implementations</div><h1>ClearHot Six-Method Workbench</h1><p>One local preview combining three Argos methods and three Claude methods. Choose a method below, or open both original workspaces.</p><p class="muted">The algorithm implementations are retained. This shell adds navigation and optional shared-file / frame controls; it also resets Argos temporal state on source changes and discontinuous seeks.</p></div></header>
<div class="note"><b>Experimental preview, not validated for operational use.</b> All six can remove real scene features. Synthetic benchmarks, scores and “best” labels do not prove real-data performance; original claims about ghosting, target retention, CNNs and FPGA resources are not established. See the accompanying independent review.</div>
<main><div class="tools"><label class="file">Load one .bin for both workspaces<input id="file" type="file" accept=".bin,.raw"></label><div><div id="source">Separate synthetic scenes by default</div><div class="status" id="status" role="status">Preparing workspaces…</div></div><div class="seek"><label for="frame">Shared file frame: <b id="frame-label">1 / 1</b></label><input id="frame" type="range" min="0" max="0" value="0" disabled></div></div><p class="foot">The shared input assumes headerless 640×512 uint16, little-endian, lower 14 bits; matching file length does not prove format. 200 MiB cap in this combined view. File is read locally. Both workspaces must report loaded before the shared frame control is enabled. Their individual controls can change state independently; synthetic scenes differ between apps. The preview resets Argos state on file changes and non-consecutive seeks, which also resets Argos settings on file load. Start paused and expect high CPU/memory use, especially at full resolution. In the viewer sandbox, downloads and model persistence may not work; open the downloaded HTML in a normal browser if needed.</p>
<div class="tabs-title">Choose one of the six</div><nav class="nav" aria-label="Six methods"><button class="active" data-mode="argos1">Argos 1 · Edge gated</button><button data-mode="argos2">Argos 2 · Wavelet</button><button data-mode="argos3">Argos 3 · Bilateral / temporal</button><button data-mode="claudeA">Claude A · Robust spatial</button><button data-mode="claudeB">Claude B · Multi-frame</button><button data-mode="claudeC">Claude C · Spectral</button><button data-mode="both">Both workspaces</button></nav>
<div class="description" id="desc"></div><div class="grid" id="grid"><section class="pane" id="pane-argos"><h2>ARGOS · original interactive workspace</h2><iframe id="argos" title="Argos thermal workbench" sandbox="allow-scripts allow-downloads"></iframe></section><section class="pane" id="pane-claude" hidden><h2>CLAUDE · original interactive workspace</h2><iframe id="claude" title="Claude thermal workbench" sandbox="allow-scripts allow-downloads"></iframe></section></div><p class="foot">Review numbers are proxies or synthetic-reference measurements. Processed display is not radiometric ground truth. No trained real-data model, FPGA synthesis, real-time throughput or real challenge-file evaluation is included.</p></main>
<script>
'use strict';
const encoded={argos:'__ARGOS__',claude:'__CLAUDE__'};
const $=id=>document.getElementById(id), frames={argos:$('argos'),claude:$('claude')},ready={argos:false,claude:false},loaded={argos:false,claude:false};let currentFile=null,frameCount=1,mode='argos1';
const choices={argos1:{engine:'argos',tab:'inst1',text:'Argos 1 · Edge-gated differential line correction, rank filtering and multi-scale detail. An independent synthetic probe found the default settings did not reduce a strong alternating-column pattern; real performance remains unknown.'},argos2:{engine:'argos',tab:'inst2',text:'Argos 2 · Haar/wavelet profile processing with guided base/detail enhancement. Examine edge and fine-feature loss rather than relying on the built-in winner label.'},argos3:{engine:'argos',tab:'inst3',text:'Argos 3 · Cross-bilateral profile processing with optional temporal smoothing. Motion gates do not establish zero ghosting.'},claudeA:{engine:'claude',tab:'A',text:'Claude A · Robust local-median spatial offsets and CLAHE. Synthetic tests show improvement for their fixtures, but some real full-height scene lines were also suppressed.'},claudeB:{engine:'claude',tab:'B',text:'Claude B · Multi-frame averaging and guided enhancement. At the start of a recording, its window uses later frames; it is not strictly real-time causal in that case.'},claudeC:{engine:'claude',tab:'C',text:'Claude C · Spectral profile filtering, bilateral denoising and multi-scale detail. Results and times are synthetic and device-dependent.'},both:{engine:'both',text:'Both original workspaces are visible below: Argos three-way view and Claude comparison. Their source generators, metrics, processing stages and settings differ, so their scores are not directly comparable.'}};
function send(e,msg){if(ready[e])frames[e].contentWindow.postMessage({channel:'six-thermal-v1',...msg},'*')}
function setMode(next){mode=next;document.querySelectorAll('[data-mode]').forEach(b=>{const on=b.dataset.mode===mode;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))});let c=choices[mode];$('desc').textContent=c.text;$('pane-argos').hidden=c.engine==='claude';$('pane-claude').hidden=c.engine==='argos';$('grid').classList.toggle('both',c.engine==='both');if(c.engine==='both'){send('argos',{kind:'select',tab:'all3'});send('claude',{kind:'select',tab:'compare'})}else send(c.engine,{kind:'select',tab:c.tab})}
function status(){const s=$('status');if(currentFile)s.textContent=`${loaded.argos?'✓':'…'} Argos · ${loaded.claude?'✓':'…'} Claude ${loaded.argos&&loaded.claude?'loaded':'loading or waiting'} · `+currentFile.name;else s.textContent=`Workspaces: Argos ${ready.argos?'ready':'loading'} · Claude ${ready.claude?'ready':'loading'}`;$('frame').disabled=!(currentFile&&loaded.argos&&loaded.claude)}
window.addEventListener('message',e=>{let d=e.data;if(!d||d.channel!=='six-thermal-v1'||!['argos','claude'].includes(d.engine)||e.source!==frames[d.engine].contentWindow)return;if(d.kind==='ready'){ready[d.engine]=true;if(currentFile)send(d.engine,{kind:'file',file:currentFile});setMode(mode);status()}else if(d.kind==='loaded'&&currentFile&&d.fileName===currentFile.name){loaded[d.engine]=!!d.ok;status();if(!d.ok){$('status').textContent=d.engine+' could not load the file. Check the workspace for its error.';$('status').classList.add('error')}else if(loaded.argos&&loaded.claude){send('argos',{kind:'frame',frame:0});send('claude',{kind:'frame',frame:0})}}});
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));
$('file').addEventListener('change',e=>{const f=e.target.files?.[0];e.target.value='';if(!f)return;const bytes=640*512*2;if(!f.size||f.size%bytes!==0||f.size>200*1024*1024){$('status').textContent='Not loaded: file must contain whole 655,360-byte frames and be at most 200 MiB.';$('status').classList.add('error');return}currentFile=f;loaded.argos=loaded.claude=false;frameCount=f.size/bytes;$('frame').max=frameCount-1;$('frame').value=0;$('frame-label').textContent='1 / '+frameCount;$('source').textContent='Shared file: '+f.name;$('status').classList.remove('error');status();send('argos',{kind:'file',file:f});send('claude',{kind:'file',file:f})});
$('frame').addEventListener('input',e=>{const n=Number(e.target.value);$('frame-label').textContent=(n+1)+' / '+frameCount;send('argos',{kind:'frame',frame:n});send('claude',{kind:'frame',frame:n})});
function decode(s){const bin=atob(s),buf=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)buf[i]=bin.charCodeAt(i);return new TextDecoder().decode(buf)}
frames.argos.srcdoc=decode(encoded.argos);frames.claude.srcdoc=decode(encoded.claude);setMode(mode);status();
</script></body></html>'''
page=page.replace('__ARGOS__',argos).replace('__CLAUDE__',claude)
(BASE/'ClearHot_Six_Method_Workbench.html').write_text(page,encoding='utf8')
print('bytes',len(page.encode()))
